'use strict';
/* Parcours de partage. Montants et états viennent exclusivement de l’API. */
(function(){
 let epoch=0,scopedUser=null;const keys=new Map();const redirected=new Set();
 const labels={completed:'Analyse terminée',not_available:'Non disponible',draft:'Brouillon',analysis_completed:'Analyse terminée',internal_review:'Revue interne',second_validation:'Seconde validation attendue',needs_completion:'À compléter',approved:'Validé par notre institution',not_approved:'Non approuvé en interne',superseded:'Nouvelle analyse et validation requises',ready:'Prêt à confirmer',pending:'En attente de transmission',sending:'Transmission en cours',transmitted:'Envoyé à la banque',received:'Réception confirmée',under_review:'En cours d’étude',additional_information:'Complément demandé',decision_available:'Décision de la banque',failed:'Échec technique',withdrawn:'Demande retirée',cancelled:'Envoi annulé',valid:'Valide',expired:'Expirée',revoked:'Révoquée',replaced:'Remplacée',favorable_opinion:'Avis favorable',conditional_offer:'Offre conditionnelle',formal_offer:'Offre formelle',refused:'Refus',disbursement_confirmed:'Décaissement confirmé selon la déclaration bancaire'};
 const categories={identification:'Fiche d’identification',credit_request:'Demande de financement',declaration:'Déclaration financière',budget:'Budget et flux',debts:'Dettes et engagements',lender_report:'Rapport destiné au prêteur',analysis_summary:'Synthèse des risques et suggestions',inventory:'Inventaire documentaire',attestation:'Attestation de validation interne'};
 const esc=v=>String(v??'Non disponible').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const text=v=>esc(labels[v]||v);const cat=v=>esc(categories[v]||v);
 const services=()=>window.CreditServices;
 const isBank=()=>['bank_agent','bank_manager'].includes(services()?.user?.role);
 const key=s=>{if(!keys.has(s))keys.set(s,crypto.randomUUID());return keys.get(s)};
 const path=c=>'/'+c.core+'/'+encodeURIComponent(c.id);
 function context(current){const p=current.split('/');if(['individuals','businesses'].includes(p[1])&&p[2])return {core:p[1],id:p[2]};const d=window.CreditJourney?.getDraft();return d?.remote?.id?{core:d.core,id:d.remote.id}:null}
 function title(t,sub){document.querySelector('#page-title').textContent=t;document.querySelector('#page-subtitle').textContent=sub}
 function button(label,id,klass='outline'){return '<button class="'+klass+'" id="'+id+'">'+label+'</button>'}
 function message(error){toast(error.message||'Opération non confirmée. Actualisez son état avant de réessayer.');}
 function bind(root,id,action){const el=root.querySelector('#'+id);if(!el)return;el.onclick=async()=>{if(el.disabled)return;el.disabled=true;try{await action()}catch(e){message(e)}finally{if(el.isConnected)el.disabled=false}}}
 function table(obj){return '<div class="table-scroll"><table><thead><tr><th>ÉLÉMENT</th><th>VALEUR SERVEUR</th></tr></thead><tbody>'+Object.entries(obj).map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+esc(v===null?'Indisponible':typeof v==='object'?JSON.stringify(v):v)+'</td></tr>').join('')+'</tbody></table></div>'}
 async function download(api,url){const blob=await api.request(url,{responseType:'blob'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=url.endsWith('/archive')?'dossier-bancaire.zip':blob.type==='application/pdf'?'document-credit-pme.pdf':'document-credit-pme';a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)}
 function notice(demo){return '<div class="mode-notice"><span class="mode-dot"></span><div><strong>'+ (demo?'DÉMONSTRATION · banque fictive':'Transmission choisie par le demandeur')+'</strong><span>Validation interne, attestation, transmission et décision bancaire sont distinctes.</span></div></div>'}
 async function caseList(view,api){title('Choisir ma banque.','Reprendre une transmission liée à une version approuvée.');const rows=(await Promise.all(['/individuals','/businesses'].map(x=>api.request(x)))).flat();return '<section class="form-panel"><h2>Mes dossiers</h2>'+rows.map(c=>'<p><a class="text-button" href="#bank-choice/'+c.kind+'/'+c.id+'">'+esc(c.data.name)+' · choisir ou suivre ma banque ↗</a></p>').join('')+(rows.length?'':'<p>Aucun dossier autorisé disponible.</p>')+'</section>'}
 async function choice(view,api,c){if(!c)return caseList(view,api);const data=await api.request(path(c)+'/banking');title('Choisir ma banque.','Une validation interne ne constitue pas une promesse de financement.');const review=data.reviews.find(r=>r.state==='approved'&&r.attestation?.state==='valid');
  let html=button('Actualiser la validation et les partenaires','bank-choice-refresh')+notice(review?.attestation?data.partners.some(p=>p.demonstration):false)+'<section class="form-panel"><h2>'+text(data.internal_state)+'</h2><p>Version du dossier : '+data.case_version+'. Analyse : '+text(data.analysis_state)+'.</p>';
  if(review)html+='<p>Validé par notre institution le '+esc(review.approved_at)+'. Attestation '+esc(review.attestation.id)+' · '+text(review.attestation.state)+'.</p><a class="text-button" href="'+esc(review.attestation.verification_url)+'" target="_blank" rel="noopener">Vérifier le statut minimal ↗</a>';
  else html+='<p>Une analyse terminée, une approbation interne actuelle et une attestation signée utilisable sont nécessaires. Le serveur interdira toute préparation avant ces étapes.</p>'+button('Demander la revue institutionnelle','request-review-access');
  html+=(data.reviews[0]?.public_decisions||[]).filter(d=>d.public_reserves).map(d=>'<p><strong>'+text(d.decision)+' :</strong> '+esc(d.public_reserves)+'</p>').join('');html+='</section><section class="section-explorer"><h2>Banques réellement activées pour ce dossier</h2><div class="section-grid">'+data.partners.map(p=>'<article class="form-panel"><span class="mini-kicker">'+esc(p.demonstration?'BANQUE FICTIVE':'PARTENAIRE ACTIVÉE')+'</span><h3>'+esc(p.name)+'</h3><p>'+esc(p.presentation)+'</p><p>'+esc(p.activity_scope)+' · '+esc(p.country)+'</p><p>Conditions fournies : '+esc(p.provided_conditions||'Aucune condition commerciale fournie')+'</p><small>Mise à jour : '+esc(p.information_updated_on)+'</small><p>'+esc(p.processing_notice)+'</p>'+button('Choisir et prévisualiser','select-bank-'+p.id,'primary')+'</article>').join('')+'</div>'+(data.partners.length?'':'<p class="calm-note">Aucune banque activée et compatible n’est disponible. Aucune transmission n’a été effectuée.</p>')+'</section><section class="form-panel"><h2>Mes transmissions</h2>'+data.transmissions.map(t=>'<p><a class="text-button" href="#bank-tracking/'+t.id+'">'+esc(t.partner_name)+' · '+text(t.state)+' · version '+t.case_version+' ↗</a></p>').join('')+'</section>';
  return {html,bind:()=>{bind(view,'bank-choice-refresh',async()=>window.renderApp());bind(view,'request-review-access',async()=>{await api.request(path(c)+'/banking/review-access',{method:'POST'});toast('Accès de l’équipe habilitée demandé. Aucune approbation automatique.');window.renderApp()});for(const p of data.partners)bind(view,'select-bank-'+p.id,()=>selectFiles(view,api,c,p,review,data.transmissions))}};
 }
 function selectFiles(view,api,c,partner,review,existing){const required=new Set(partner.required_categories);const chosen=new Set();for(const category of required){const f=review.files.find(f=>f.category===category);if(f)chosen.add(f.id)}const available=review.files.filter(f=>partner.allowed_categories.includes(f.category));
  openModal('<h2>Ce qui sera proposé à '+esc(partner.name)+'</h2><p>Choisissez les pièces autorisées. La préparation ne transmet rien à la banque.</p><form id="bank-files-form">'+available.map(f=>'<label class="check-field"><input type="checkbox" name="files" value="'+esc(f.id)+'" '+(chosen.has(f.id)?'checked':'')+'><span>'+cat(f.category)+' · '+esc(f.name)+' · '+f.size+' octets</span></label><button type="button" class="text-button" data-review-file="'+esc(f.id)+'">Consulter cette pièce ↗</button>').join('')+'<button class="primary" type="submit">Prévisualiser le paquet sélectionné →</button><p role="status" id="bank-files-error"></p></form>','PARTAGE EXPLICITE');
  document.querySelectorAll('[data-review-file]').forEach(b=>b.onclick=()=>download(api,'/internal-reviews/'+review.id+'/files/'+b.dataset.reviewFile).catch(message));
  document.querySelector('#bank-files-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{const ids=new FormData(e.target).getAll('files');const same=existing.find(t=>t.state==='ready'&&t.partner_id===partner.id&&t.manifest.review_id===review.id&&JSON.stringify(t.manifest.files.map(f=>f.id).sort())===JSON.stringify([...ids].sort()));const body={partner_id:partner.id,review_id:review.id,file_ids:ids};const t=same||await api.request(path(c)+'/banking/previews',{method:'POST',body,key:key('prepare:'+JSON.stringify(body)),timeoutMs:120000});document.querySelector('#modal').close();location.hash='bank-tracking/'+t.id}catch(err){document.querySelector('#bank-files-error').textContent=err.message+' En cas de résultat incertain, actualisez le suivi avant de recommencer.'}finally{submit.disabled=false}};
 }
 async function institution(view,api,c){if(!services().staff)throw Error('Revue réservée aux agents habilités.');if(!c)return caseList(view,api);const data=await api.request(path(c)+'/banking');const analyses=await api.request(path(c)+'/assessments');title('Revue interne.','Approuver une version précise, indépendamment de la décision bancaire.');const active=data.reviews[0];const sources=[];const subs=await api.request(path(c)+'/submissions');for(const sub of subs)for(const s of sub.sources||[...new Set((sub.pages||[]).map(p=>p.source_id))].map(id=>({id})))sources.push({...s,category:sub.document_type});
  let html='<section class="form-panel"><h2>Constituer une nouvelle revue</h2><p>Version du dossier : '+data.case_version+'. Les notes internes sont exclues du paquet bancaire.</p><form id="internal-review-start"><label class="field"><span>Analyse principale à examiner</span><select name="analysis" required>'+analyses.filter(a=>!a.parent_id).map(a=>'<option value="'+esc(a.id)+'">'+esc(a.created_at)+' · '+esc(a.engine_version)+' · '+esc(a.id)+'</option>').reverse().join('')+'</select></label><fieldset class="admin-review-sources"><legend>Pièces originales à inclure dans le paquet de revue</legend><p>Sélection explicite. Aucune pièce ni note interne n’est ajoutée automatiquement.</p>'+sources.map(s=>'<label class="check-field"><input type="checkbox" name="source_ids" value="'+esc(s.id)+'"><span>'+cat(s.category)+' · '+esc(s.name||s.id)+'</span></label>').join('')+'</fieldset><label class="field"><span>Justificatif du pouvoir d’agir, si exigé</span><select name="authority_source"><option value="">Aucun justificatif sélectionné</option>'+sources.map(s=>'<option value="'+esc(s.id)+'">'+cat(s.category)+' · '+esc(s.name||s.id)+'</option>').join('')+'</select></label><button class="primary" type="submit">Figer le paquet et ouvrir la revue</button><p role="status" id="review-start-error"></p></form></section>';
  if(active)html+='<section class="form-panel"><h2>'+text(active.state)+'</h2><p>'+active.approvals_count+' validation(s) sur '+active.required_approvals+' requise(s). Dossier version '+active.case_version+'.</p>'+table({Analyse:active.assessment_id,'Empreinte approuvée':active.manifest_sha256})+'<div class="inline-buttons">'+active.files.map(f=>button(cat(f.category)+' ↗','review-download-'+f.id)).join('')+'</div>'+(['internal_review','second_validation'].includes(active.state)?'<form id="review-decision"><label class="field"><span>Motif interne de la décision</span><textarea name="reason" minlength="10" required></textarea></label><label class="field"><span>Réserves communicables au demandeur et à la banque</span><textarea name="reserves"></textarea></label><label class="field"><span>Décision interne</span><select name="decision"><option value="approve">Approuver en interne</option><option value="needs_completion">Demander des compléments</option><option value="not_approved">Ne pas approuver</option></select></label><label class="check-field"><input type="checkbox" name="packet_preview"><span>Pour approuver, j’autorise la prévisualisation privée de ce paquet bancaire par le demandeur. Les notes internes en sont exclues.</span></label><button class="primary" type="submit">Enregistrer la décision habilitée</button><p id="review-decision-error" role="status"></p></form>':'')+(active.state==='approved'?button('Émettre ou consulter l’attestation signée','issue-attestation','primary'):'')+'<p>L’émission exige une clé configurée. Le nom imprimé n’est pas une signature électronique certifiée.</p></section>';
  return {html,bind:()=>{const form=view.querySelector('#internal-review-start');form.onsubmit=async e=>{e.preventDefault();const values=new FormData(form),body={assessment_id:values.get('analysis'),expected_case_version:data.case_version,source_ids:values.getAll('source_ids'),business_authority_source_id:values.get('authority_source')||null};form.querySelector('button').disabled=true;try{await api.request(path(c)+'/internal-reviews',{method:'POST',body,key:key('review:'+JSON.stringify(body)),timeoutMs:120000});window.renderApp()}catch(err){view.querySelector('#review-start-error').textContent=err.message;form.querySelector('button').disabled=false}};
   if(active){for(const f of active.files)bind(view,'review-download-'+f.id,()=>download(api,'/internal-reviews/'+active.id+'/files/'+f.id));const decision=view.querySelector('#review-decision');if(decision)decision.onsubmit=async e=>{e.preventDefault();const fields=new FormData(decision);decision.querySelector('button').disabled=true;try{const r=await api.request('/internal-reviews/'+active.id+'/decisions',{method:'POST',body:{expected_revision:active.revision,decision:fields.get('decision'),reason:fields.get('reason'),public_reserves:fields.get('reserves'),authorize_packet_preview:fields.has('packet_preview')}});if(r.state==='approved')toast('Validé en interne. Émettez l’attestation ; le demandeur pourra ensuite choisir sa banque.');window.renderApp()}catch(err){view.querySelector('#review-decision-error').textContent=err.message;decision.querySelector('button').disabled=false}};bind(view,'issue-attestation',async()=>{await api.request('/internal-reviews/'+active.id+'/attestation',{method:'POST',timeoutMs:120000});window.renderApp()})}}};
 }
 async function tracking(view,api,id,bancaire){const prefix=(bancaire?'/bank':'')+'/transmissions/'+encodeURIComponent(id);const t=await api.request(prefix);const events=await api.request(prefix+'/events');title(bancaire?'Espace de réception bancaire.':'Suivre ma demande.','Chaque état correspond à un événement enregistré.');
  let html=notice(t.demonstration)+'<section class="form-panel"><h2>'+text(t.state)+'</h2><p>'+esc(t.partner_name)+' · dossier version '+t.case_version+' · suivi '+esc(t.id)+'</p><p>Attestation '+esc(t.attestation_id)+' : '+text(t.attestation_status)+'.</p>'+table(t.financing)+'<p>'+esc(t.processing_notice)+'</p>'+(t.failure?'<p class="calm-note">'+esc(t.failure)+'</p>':'')+(t.decision?'<h3>'+text(t.decision.kind)+'</h3><p>'+esc(t.decision.reason)+'</p>':'')+'<div class="inline-buttons">'+button('Actualiser le suivi','bank-refresh')+button('Archive du paquet et signature détachée','bank-archive')+(bancaire?button('Vérifier l’intégrité et l’attestation','bank-verify'):'')+'</div></section><section class="form-panel"><h2>Documents sélectionnés</h2>'+t.manifest.files.map(f=>'<p>'+cat(f.category)+' · '+esc(f.name)+' · '+esc(f.sha256)+' '+button('Télécharger ↗','packet-file-'+f.id)+'</p>').join('')+'</section>';
  if(!bancaire&&t.state==='ready')html+='<section class="form-panel"><h2>Confirmer ce partage précis</h2><p>'+esc(t.consent_text)+'</p><p>Texte '+esc(t.consent_version)+' · manifeste '+esc(t.manifest_sha256)+'</p><form id="bank-confirm-form"><label class="field"><span>Votre qualité et votre pouvoir d’agir pour cette demande</span><textarea name="authority" minlength="10" required></textarea></label><label class="check-field"><input type="checkbox" name="accepted" required><span>Je confirme le destinataire et le partage de ces documents pour l’étude de ce financement.</span></label><button class="primary" type="submit">Confirmer et mettre en transmission →</button><p role="status" id="bank-confirm-error"></p></form></section>';
  if(!bancaire&&t.state==='pending')html+='<section class="form-panel"><p>La transmission est en file d’attente. Le worker la traite, ou vous pouvez déclencher une tentative autorisée.</p>'+button('Lancer la transmission en attente','bank-dispatch','primary')+'</section>';
  if(!bancaire&&!['withdrawn','cancelled'].includes(t.state))html+='<section class="form-panel">'+button('Retirer cette demande','bank-withdraw')+'<p>Le retrait n’efface pas les copies déjà reçues ou téléchargées.</p></section>';
  if(bancaire&&!['withdrawn','cancelled'].includes(t.state))html+='<section class="form-panel"><h2>Traitement bancaire</h2><form id="bank-event-form"><label class="field"><span>Événement</span><select name="action"><option value="received">Confirmer la réception</option><option value="under_review">En cours d’étude</option><option value="additional_information">Demander un complément</option><option value="decision">Communiquer une décision</option></select></label><label class="field"><span>Motif communiqué au demandeur</span><textarea name="reason" minlength="5" required></textarea></label><label class="field"><span>Compléments demandés, un par ligne</span><textarea name="requested"></textarea></label><label class="field"><span>Nature de la décision, si applicable</span><select name="decision"><option value="">Aucune décision</option>'+['favorable_opinion','conditional_offer','formal_offer','refused','disbursement_confirmed'].map(x=>'<option value="'+x+'">'+text(x)+'</option>').join('')+'</select></label><label class="field"><span>Référence externe bancaire</span><input name="reference"></label><label class="field"><span>Identifiants des pièces de réponse à communiquer, séparés par des virgules</span><input name="attachments"></label><button class="primary" type="submit">Enregistrer l’événement bancaire</button><p role="status" id="bank-event-error"></p></form></section>';
  if(['received','under_review','additional_information','decision_available'].includes(t.state))html+='<section class="form-panel"><h2>'+ (bancaire?'Pièces de réponse bancaire':'Répondre à une demande de complément')+'</h2><p>Le dépôt seul ne partage pas la pièce. Confirmez les compléments ou associez la réponse à un événement bancaire.</p><input type="file" id="bank-attachment-file" accept="application/pdf,image/jpeg,image/png">'+button('Déposer cette pièce','bank-upload')+'<div>'+t.attachments.map(f=>'<p>'+esc(f.id)+' · '+(f.shared?'Communiquée':'Non partagée')+' '+button('Télécharger ↗','attachment-'+f.id)+'</p>').join('')+'</div>'+(!bancaire&&t.state==='additional_information'?'<form id="bank-supplement-form"><label class="field"><span>Identifiants des pièces complémentaires à transmettre</span><input name="ids" required></label><label class="field"><span>Objet du complément</span><input name="reason" minlength="5" required></label><label class="check-field"><input type="checkbox" name="accepted" required><span>Je confirme le partage de ces compléments avec cette seule banque. Ils ne remplacent pas l’attestation initiale.</span></label><button class="primary" type="submit">Communiquer ces compléments</button><p id="supplement-error" role="status"></p></form>':'')+'</section>';
  html+='<section class="form-panel"><h2>Historique et notifications</h2>'+ (t.requested_information.length?'<h3>Pièces ou informations demandées</h3><ul>'+t.requested_information.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+events.map(e=>'<p>'+esc(e.date)+' · '+text(e.event)+' · '+esc(e.data.reason||e.data.notice||'')+'</p>').join('')+'</section>';
  return {html,bind:()=>{bind(view,'bank-refresh',async()=>window.renderApp());bind(view,'bank-archive',()=>download(api,prefix+'/archive'));for(const f of t.manifest.files)bind(view,'packet-file-'+f.id,()=>download(api,prefix+'/files/'+f.id));for(const f of t.attachments)bind(view,'attachment-'+f.id,()=>download(api,prefix+'/attachments/'+f.id));
   bind(view,'bank-dispatch',async()=>{await api.request(prefix+'/dispatch',{method:'POST',timeoutMs:120000});window.renderApp()});
   bind(view,'bank-verify',async()=>{const r=await api.request(prefix+'/verify');openModal('<h2>Vérification du paquet reçu</h2>'+table(r)+'<p>La validité cryptographique est distincte de la confiance juridique dans l’émetteur.</p>','INTÉGRITÉ')});
   const confirm=view.querySelector('#bank-confirm-form');if(confirm)confirm.onsubmit=async e=>{e.preventDefault();if(!confirm.reportValidity())return;confirm.querySelector('button').disabled=true;const values=new FormData(confirm);try{await api.request(prefix+'/confirm',{method:'POST',body:{expected_revision:t.revision,manifest_sha256:t.manifest_sha256,attestation_id:t.attestation_id,consent_version:t.consent_version,accepted:values.has('accepted'),authority_statement:values.get('authority')}});window.renderApp()}catch(err){view.querySelector('#bank-confirm-error').textContent=err.message+' Actualisez l’état avant de recommencer.';confirm.querySelector('button').disabled=false}};
   bind(view,'bank-withdraw',async()=>{openModal('<h2>Retirer cette demande</h2><p>Une copie reçue par la banque ne peut pas être effacée à distance.</p><form id="withdraw-form"><label class="field"><span>Motif</span><textarea name="reason" minlength="5" required></textarea></label><button class="primary" type="submit">Confirmer le retrait</button></form>','RETRAIT EXPLICITE');document.querySelector('#withdraw-form').onsubmit=async e=>{e.preventDefault();try{await api.request(prefix+'/withdraw',{method:'POST',body:{reason:new FormData(e.target).get('reason')}});document.querySelector('#modal').close();window.renderApp()}catch(err){message(err)}}});
   const form=view.querySelector('#bank-event-form');if(form)form.onsubmit=async e=>{e.preventDefault();const values=new FormData(form);const body={expected_revision:t.revision,action:values.get('action'),reason:values.get('reason'),requested_information:String(values.get('requested')).split('\n').map(x=>x.trim()).filter(Boolean),decision:values.get('decision')||null,external_reference:values.get('reference')||null,attachment_ids:String(values.get('attachments')).split(',').map(x=>x.trim()).filter(Boolean)};form.querySelector('button').disabled=true;try{await api.request(prefix+'/events',{method:'POST',body,key:key('event:'+id+JSON.stringify(body))});window.renderApp()}catch(err){view.querySelector('#bank-event-error').textContent=err.message;form.querySelector('button').disabled=false}};
   bind(view,'bank-upload',async()=>{const file=view.querySelector('#bank-attachment-file').files[0];if(!file)throw Error('Choisissez un PDF, JPEG ou PNG.');const r=await api.request(prefix+'/attachments',{method:'POST',body:file,binary:true,timeoutMs:120000});toast('Pièce déposée : '+r.id+' ; aucune communication automatique.');window.renderApp()});
   const sup=view.querySelector('#bank-supplement-form');if(sup)sup.onsubmit=async e=>{e.preventDefault();const fields=new FormData(sup),body={expected_revision:t.revision,reason:fields.get('reason'),attachment_ids:String(fields.get('ids')).split(',').map(x=>x.trim()).filter(Boolean),accepted:fields.has('accepted')};sup.querySelector('button').disabled=true;try{await api.request(prefix+'/supplements',{method:'POST',body,key:key('supplement:'+id+JSON.stringify(body))});window.renderApp()}catch(err){view.querySelector('#supplement-error').textContent=err.message;sup.querySelector('button').disabled=false}};
  }};
 }
 async function inbox(view,api){title('Les dossiers transmis.','Réception et décision bancaire restent deux étapes distinctes.');const data=await api.request('/bank/inbox');return '<section class="form-panel"><h2>Boîte de réception bancaire</h2>'+button('Actualiser','bank-inbox-refresh')+data.map(t=>'<article class="account-detail-card"><span class="mini-kicker">'+esc(t.demonstration?'DÉMONSTRATION':'VERSION TRANSMISE')+'</span><h3>'+text(t.state)+'</h3><p>Suivi '+esc(t.id)+' · version '+t.case_version+'</p><a class="text-button" href="#bank-received/'+t.id+'">Consulter le paquet autorisé ↗</a></article>').join('')+(data.length?'':'<p>Aucun dossier transmis à votre institution.</p>')+'</section>'}
 function route(view,current){const s=services();if(scopedUser!==s?.user?.id){keys.clear();redirected.clear();scopedUser=s?.user?.id}const handled=current.startsWith('bank-')||current.startsWith('institution-review')||(s?.ready&&isBank()&&!['profile','settings'].includes(current));if(!handled){epoch++;return false}const seq=++epoch;const api=s?.api;view.innerHTML='<section class="form-panel"><h2>Chargement du parcours sécurisé…</h2></section>';if(!s?.ready||!api){view.innerHTML='<section class="form-panel"><h2>Connexion requise</h2><p>Aucun accès bancaire sans vérification des droits côté serveur.</p><a class="text-button" href="#profile">Se connecter →</a></section>';return true}
  const task=current.startsWith('bank-tracking/')?tracking(view,api,current.split('/')[1],false):current.startsWith('bank-received/')?tracking(view,api,current.split('/')[1],true):current.startsWith('institution-review')?institution(view,api,context(current)):isBank()?inbox(view,api):choice(view,api,context(current));Promise.resolve(task).then(result=>{if(seq!==epoch||s.api!==api||!s.ready)return;view.innerHTML=typeof result==='string'?result:result.html;result.bind?.();bind(view,'bank-inbox-refresh',async()=>window.renderApp())}).catch(error=>{if(seq!==epoch||s.api!==api)return;view.innerHTML='<section class="form-panel"><h2>Parcours indisponible</h2><p>'+esc(error.message)+'</p>'+button('Actualiser sans nouvel envoi','bank-retry-view')+'</section>';bind(view,'bank-retry-view',async()=>window.renderApp())});return true;
 }
 function mount(view,current){const s=services();if(!s?.ready||s.user?.role==='administrator')return;const d=window.CreditJourney?.getDraft();if(!view.querySelector('#bank-journey-link')){const section=document.createElement('section');section.className='form-panel';section.id='bank-journey-link';section.innerHTML=isBank()?'<a class="text-button" href="#bank-inbox">Espace bancaire · réception et suivi ↗</a>':'<a class="text-button" href="#bank-choice">Choisir ma banque et suivre mes transmissions ↗</a>'+(s.staff&&d?.remote?.id?' <a class="text-button" href="#institution-review/'+d.core+'/'+d.remote.id+'">Revue interne et attestation ↗</a>':'');view.append(section)}
  if(s.user.role==='applicant'&&d?.remote?.id&&['overview','requests','analysis'].includes(current)){const api=s.api;const caseId=d.remote.id;api.request('/'+d.core+'/'+caseId+'/banking').then(data=>{if(s.api!==api||!s.ready||window.CreditJourney?.getDraft()?.remote?.id!==caseId)return;const r=data.reviews.find(r=>r.state==='approved'&&r.attestation?.state==='valid');if(r&&!redirected.has(r.id)){redirected.add(r.id);location.hash='bank-choice/'+d.core+'/'+caseId}}).catch(()=>{})}
 }
 window.CreditBanking={route,mount,reviewPanel:institution};
})();
